def hard_alpha_cutout(img_path, thresh=238):
    im = Image.open(img_path).convert("RGBA")
    arr = np.array(im)
    # Hard alpha cutout: solid white/near-white is transparent (alpha=0), rest is 100% opaque (alpha=255)
    is_bg = (arr[:, :, 0] >= thresh) & (arr[:, :, 1] >= thresh) & (arr[:, :, 2] >= thresh)
    arr[is_bg, 3] = 0
    arr[~is_bg, 3] = 255
    cutout = Image.fromarray(arr, mode="RGBA")
    bbox = cutout.getbbox()
    if bbox:
        return cutout.crop(bbox)
    return cutout

def scale_nearest(im, target_w):
    scale = target_w / float(im.width)
    target_h = max(1, round(im.height * scale))
    return im.resize((target_w, target_h), resample=Image.Resampling.NEAREST)

def run():
    raw_files = sorted(glob.glob(os.path.join(BASE_DIR, "Gambar ChatGPT*.png")))
    if len(raw_files) != 30:
        # Check if already in raw
        raw_files = sorted(glob.glob(os.path.join(RAW_DIR, "Gambar ChatGPT*.png")))
    
    print(f"Found {len(raw_files)} raw files to process.")
    assert len(raw_files) == 30, f"Expected 30 files, got {len(raw_files)}"

    summary = []

    for cfg in ASSET_CONFIG:
        idx, cat, filename, target_w, slices = cfg
        src_file = raw_files[idx - 1]
        
        target_dir = os.path.join(BASE_DIR, cat)
        os.makedirs(target_dir, exist_ok=True)
        out_path = os.path.join(target_dir, filename)

        # 1. Hard alpha cutout & bounding box crop
        cropped = hard_alpha_cutout(src_file)
        
        # 2. Nearest Neighbor rescaling
        scaled = scale_nearest(cropped, target_w)
        scaled.save(out_path, format="PNG")
        
        item_info = {
            "id": idx,
            "category": cat,
            "filename": filename,
            "orig_size": Image.open(src_file).size,
            "cutout_size": cropped.size,
            "scaled_size": scaled.size,
            "slices": []
        }

        # 3. Process slices if applicable
        if slices:
            num_slices = len(slices)
            slice_w = target_w // num_slices
            h = scaled.height
            for s_name, s_idx in slices:
                s_box = (s_idx * slice_w, 0, (s_idx + 1) * slice_w, h)
                s_img = scaled.crop(s_box)
                s_path = os.path.join(target_dir, s_name)
                s_img.save(s_path, format="PNG")
                item_info["slices"].append((s_name, s_img.size))

        summary.append(item_info)
        print(f"[{idx:02d}] {cat}/{filename} -> {scaled.size} (slices: {len(slices) if slices else 0})")

    # Move raw files to raw/ if still in BASE_DIR
    for f in glob.glob(os.path.join(BASE_DIR, "Gambar ChatGPT*.png")):
        dst = os.path.join(RAW_DIR, os.path.basename(f))
        shutil.move(f, dst)

    print("All 30 assets successfully processed, categorized, and archived to raw/!")

if __name__ == "__main__":
    run()
